import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import {
  Activity,
  Brain,
  ShieldAlert,
  Cpu,
  Sparkles,
  Layers,
  GraduationCap,
  UserCheck,
  User,
  LogOut,
} from 'lucide-react';
import { useLanguage } from '../../context/LanguageContext';
import { useUser } from '../../context/UserContext';
import LanguageToggle from './LanguageToggle';

interface NavbarProps {
  modelLoaded: boolean;
}

const Navbar: React.FC<NavbarProps> = ({ modelLoaded }) => {
  const { t } = useLanguage();
  const location = useLocation();
  const navigate = useNavigate();
  const { role, setRole, isStudent, user, isLoggedIn, logoutUser } = useUser();

  const handleRoleToggle = () => {
    if (isStudent) {
      setRole('patient');
      navigate('/tasks');
    } else {
      setRole('student');
      navigate('/student');
    }
  };

  const handleSignOut = () => {
    logoutUser();
    navigate('/login');
  };

  return (
    <header className="sticky top-0 z-40 w-full border-b border-slate-800/80 bg-slate-950/80 backdrop-blur-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
        {/* Brand Logo & Name */}
        <Link to="/" className="flex items-center space-x-3 group">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-teal-600 to-cyan-400 p-0.5 shadow-lg shadow-teal-500/20 group-hover:shadow-teal-500/40 transition-all">
            <div className="w-full h-full bg-slate-950 rounded-[10px] flex items-center justify-center">
              <Brain className="w-5 h-5 text-teal-400 group-hover:scale-110 transition-transform" />
            </div>
          </div>
          <div>
            <div className="flex items-center space-x-2">
              <span className="font-bold text-lg tracking-tight bg-gradient-to-r from-white via-slate-100 to-slate-400 bg-clip-text text-transparent">
                AXONOVA
              </span>
              <span className="text-[10px] uppercase tracking-wider font-semibold px-1.5 py-0.5 rounded bg-teal-500/10 text-teal-300 border border-teal-500/20">
                v1.0 • Research
              </span>
            </div>
            <p className="text-xs text-slate-400 hidden sm:block">
              {t('nav.subtitle')}
            </p>
          </div>
        </Link>

        {/* Right Action Items */}
        <div className="flex items-center space-x-2.5 sm:space-x-3">
          {/* Dedicated Medical Student Lab vs Patient Toggle Button */}
          <button
            type="button"
            onClick={handleRoleToggle}
            className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all ${
              isStudent
                ? 'bg-gradient-to-r from-purple-500/20 to-teal-500/20 text-teal-300 border-teal-500/40 hover:border-teal-400'
                : 'bg-slate-900 hover:bg-slate-800 text-purple-300 border-purple-500/30 hover:border-purple-400'
            }`}
          >
            <GraduationCap className={`w-4 h-4 ${isStudent ? 'text-teal-400' : 'text-purple-400'}`} />
            <span className="hidden sm:inline">
              {isStudent ? 'Student Mode Active' : 'Medical Student Lab'}
            </span>
          </button>

          {/* Conditions & Tasks Nav Link */}
          <Link
            to="/tasks"
            className="flex items-center space-x-1.5 px-3 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 border border-slate-800 text-xs text-slate-300 font-medium transition-colors"
          >
            <Layers className="w-3.5 h-3.5 text-teal-400" />
            <span className="hidden md:inline">Conditions</span>
          </Link>

          {/* Model Status Indicator */}
          <div className="hidden lg:flex items-center space-x-2 px-2.5 py-1 rounded-full bg-slate-900 border border-slate-800 text-xs">
            <span
              className={`w-2 h-2 rounded-full ${
                modelLoaded ? 'bg-emerald-400 animate-pulse' : 'bg-amber-400'
              }`}
            />
            <span className="text-slate-300">
              {modelLoaded ? '1 Model Active' : t('common.not_loaded')}
            </span>
          </div>

          {/* Direct Student Profile Link when in Student Mode */}
          {isStudent && (
            <Link
              to="/student/profile"
              className="flex items-center space-x-1.5 px-3 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 border border-slate-800 text-xs text-teal-300 font-medium transition-colors"
            >
              <UserCheck className="w-3.5 h-3.5 text-teal-400" />
              <span className="hidden sm:inline">Profile</span>
            </Link>
          )}

          {/* Language Switcher */}
          <LanguageToggle />

          {/* Sign Out Button */}
          {isLoggedIn && (
            <button
              type="button"
              onClick={handleSignOut}
              className="flex items-center space-x-1.5 px-2.5 py-1.5 rounded-xl bg-slate-900 hover:bg-rose-950/40 border border-slate-800 hover:border-rose-800/40 text-xs text-rose-300 transition-colors"
              title="Sign out of AXONOVA workspace"
            >
              <LogOut className="w-3.5 h-3.5 text-rose-400" />
              <span className="hidden md:inline">Sign Out</span>
            </button>
          )}
        </div>
      </div>
    </header>
  );
};

export default Navbar;
